insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$videira$q$, $q$https://diariomunicipal.sc.gov.br/atos/185181$q$, $q$Atos oficiais de Videira: domínio público (Lei 9.610/1998 art. 8º IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OSM) e limites municipais do IBGE.$q$, 61, $q$Lei 2.685/2011 relida no DOM/SC (sem alteração ou revogação localizada). Só o caminhão-trator articulado (semirreboque/CVC) é modelado; graneleiro e carga viva (por carroceria/carga) não são representáveis. O art. 2º (até 3 eixos 19h15-9h) fica desativado: área central sem perímetro. Rua Saul Brandalise e Rua XV de Novembro são também trechos da SC-355 (o ato as nomeia).$q$);
